// Des: Tests for ru-chat-file: outbox rules, size and type caps, real file chooser upload on the sim, duplicate and resume
// Flo: tmp outbox with files > check / send on the sim > read page upload list
// I/O: files and sim page > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const cf = @import("ru-chat-file.zig"); const file = @import("st-stor-file.zig"); const mock = @import("te-mock-page.zig"); const rig = @import("te-rigz-main.zig"); const T = std.testing;
fn outbox(tmpz: *std.testing.TmpDir, allo: std.mem.Allocator) ![]u8 { var pbuf: [160]u8 = undefined; const rel = try std.fmt.bufPrint(&pbuf, ".zig-cache/tmp/{s}/outb", .{tmpz.sub_path}); return mock.absPath(allo, T.io, rel); }
fn put(allo: std.mem.Allocator, dirz: []const u8, name: []const u8, body: []const u8) !void { const path = try std.fs.path.join(allo, &.{ dirz, name }); defer allo.free(path); try file.fileAtom(allo, T.io, path, body); }
test "extension allowlist is case-insensitive and needs an extension" { try T.expect(cf.extOk("a.PNG")); try T.expect(cf.extOk("x.tar.zip")); try T.expect(!cf.extOk("run.exe")); try T.expect(!cf.extOk("noext")); try T.expect(!cf.extOk(".")); }
test "check: inside the outbox, right type and size, hash is stable; traversal and absolute outside paths are refused" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const box = try outbox(&tmpz, alo); try put(alo, box, "a.txt", "hello file"); try put(alo, box, "run.exe", "MZ"); try put(alo, box, "big.txt", "0123456789"); const root = std.fs.path.dirname(box).?; try put(alo, root, "outside.txt", "secret"); const ok = try cf.check(alo, T.io, box, "a.txt", 100); try T.expectEqualStrings("a.txt", ok.name); try T.expectEqual(@as(u64, 10), ok.size); const again = try cf.check(alo, T.io, box, "a.txt", 100); try T.expectEqualStrings(&ok.hash, &again.hash); try T.expectError(error.BadJob, cf.check(alo, T.io, box, "run.exe", 100)); try T.expectError(error.TooBig, cf.check(alo, T.io, box, "big.txt", 5)); try T.expectError(error.BadJob, cf.check(alo, T.io, box, "../outside.txt", 100)); const abs_out = try std.fs.path.join(alo, &.{ root, "outside.txt" }); try T.expectError(error.BadJob, cf.check(alo, T.io, box, abs_out, 100)); try T.expectError(error.NoElem, cf.check(alo, T.io, box, "missing.txt", 100)); try T.expectError(error.BadJob, cf.check(alo, T.io, "", "a.txt", 100)); try T.expectError(error.BadJob, cf.check(alo, T.io, box, "", 100)); try T.expectError(error.BadJob, cf.check(alo, T.io, box, ".", 100)); }
test "real file chooser upload on the sim: file arrives once, duplicate is skipped, preview sends nothing" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); const alo = rg.aren.allocator(); const box = try outbox(&tmpz, alo); try put(alo, box, "report.pdf", "pdf body 123"); var cfg = rig.cfgOf(); cfg.outb_dirz_path = box; cfg.file_size_maxz = 1000; var dry = rg.ses(cfg, .dry); try T.expect(try cf.sendFile(&dry, "Mom", "report.pdf") == .dry); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.uploads.length")); var ses = rg.ses(cfg, .live); try T.expect(try cf.sendFile(&ses, "Mom", "report.pdf") == .sent); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.uploads.length")); try T.expectEqualStrings("report.pdf:12", try rg.js("Z.st.uploads[0]")); try T.expect(std.mem.find(u8, try rg.js("document.querySelector('#thread [role=article]:last-child').getAttribute('aria-label')"), "report.pdf") != null); ses.fake_ms += 600000; try T.expect(try cf.sendFile(&ses, "Mom", "report.pdf") == .dup); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.uploads.length")); }
test "refused files never reach the page; read-only is refused; crash after upload resumes without a second upload" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); const alo = rg.aren.allocator(); const box = try outbox(&tmpz, alo); try put(alo, box, "pic.png", "png"); try put(alo, box, "tool.exe", "MZ"); var cfg = rig.cfgOf(); cfg.outb_dirz_path = box; cfg.file_size_maxz = 1000; var ses = rg.ses(cfg, .live); try T.expectError(error.BadJob, cf.sendFile(&ses, "Mom", "tool.exe")); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.uploads.length")); var rdo = rg.ses(cfg, .read); try T.expectError(error.BadUsage, cf.sendFile(&rdo, "Mom", "pic.png")); try T.expect(try cf.sendFile(&ses, "Mom", "pic.png") == .sent); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.uploads.length")); try put(alo, box, "doc2.txt", "second"); const chk = try cf.check(alo, T.io, box, "doc2.txt", 1000); const key = try std.fmt.allocPrint(alo, "file:{s}", .{chk.hash[0..24]}); _ = try rg.js("Z.chats[0].msgs.push(mk('me','file','doc2.txt'));'x'"); try T.expect(try rg.sto.sendBegin("Mom", key, 1) == .fresh); ses.fake_ms += 600000; try T.expect(try cf.sendFile(&ses, "Mom", "doc2.txt") == .sent); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.uploads.length")); }
